    "Autoplan Lite": "轻量自动规划",
    "A Ling-native, gstack-inspired product -> design -> engineering -> implementation -> review/QA -> ship workflow.": "Ling 原生、借鉴 gstack 的产品 -> 设计 -> 工程 -> 实现 -> 评审/QA -> 发布工作流。",
    "Ling-native templates inspired by gstack's multi-role engineering workflow and current generic skill taxonomy. This pack does not vendor gstack runtime SKILL.md files.": "Ling 原生模板，借鉴 gstack 的多角色工程工作流和当前通用技能分类。本包不会内置 gstack runtime 的 SKILL.md 文件。",
    "Frames the problem, scope, and product tradeoffs before build work.": "在开发前框定问题、范围和产品取舍。",
    "Generate a product screenshot style image for the current task.": "为当前任务生成一张产品截图风格的图片。",
    "Owns architecture, data flow, state boundaries, and validation strategy.": "负责架构、数据流、状态边界和验证策略。",
    "Implements approved tasks and investigates failures within approval policy.": "在审批策略内实现已批准任务并调查失败。",
    "Reviews product UI, interaction quality, visual hierarchy, and workflow ergonomics.": "评审产品 UI、交互质量、视觉层级和工作流效率。",
    "Verifies behavior, regression scenarios, and user-facing workflows.": "验证行为、回归场景和用户可见工作流。",
    "Reviews trust boundaries, secrets, approvals, and abuse cases.": "评审信任边界、密钥、审批和滥用路径。",
    "Prepares release checks and publication steps under strict approval.": "在严格审批下准备发布检查和发布步骤。",
    "Keeps product, API, and workflow documentation aligned with shipped behavior.": "保持产品、API 和工作流文档与已发布行为一致。",
    "Challenge the product premise, clarify demand, and frame the work before implementation.": "挑战产品前提，澄清需求，并在实现前框定工作。",
    "Review scope and strategy before the team spends engineering time.": "在投入工程时间前评审范围和策略。",
    "Lock architecture, data flow, edge cases, and the test plan before implementation.": "实现前锁定架构、数据流、边界场景和测试计划。",
    "Review UX direction, visual system, hierarchy, and interaction gaps before UI build.": "UI 构建前评审 UX 方向、视觉系统、层级和交互缺口。",
    "Review developer-facing flows, onboarding friction, API ergonomics, and docs strategy before build.": "构建前评审开发者流程、上手摩擦、API 易用性和文档策略。",
    "Run product, design, engineering, and developer-experience reviews into one execution plan.": "把产品、设计、工程和开发者体验评审汇成一个执行方案。",
    "Turn vague intent into a precise, executable spec with scope, constraints, and validation.": "把模糊意图转成包含范围、约束和验证方式的可执行规格。",
    "Create or refresh the product design system, visual language, and DESIGN.md direction.": "创建或刷新产品设计系统、视觉语言和 DESIGN.md 方向。",
    "Explore multiple design directions and capture structured tradeoffs before committing to one.": "在定稿前探索多个设计方向并记录结构化取舍。",
    "Turn an approved design direction into production-quality frontend code under approval policy.": "在审批策略下把已批准设计方向转成生产质量前端代码。",
    "Turn an approved plan into scoped code changes while preserving approval and state boundaries.": "把已批准方案转成有范围的代码改动，并保留审批和状态边界。",
    "Trace a bug or failure from evidence to root cause before proposing fixes.": "从证据追到根因后再提出修复。",
    "Run the project's existing quality checks and summarize codebase health with trends and blockers.": "运行项目现有质量检查，并用趋势和阻塞项总结代码库健康度。",
    "Find behavioral bugs, missing tests, risky assumptions, and production failure modes.": "发现行为 bug、缺失测试、风险假设和生产失败模式。",
    "Audit the live UI for visual quality, interaction issues, and design regressions.": "审计真实 UI 的视觉质量、交互问题和设计回归。",
    "Exercise the built experience, verify user-facing behavior, and capture regressions.": "测试已构建体验，验证用户可见行为并捕获回归。",
    "Test the product surface and return a structured bug report without making code changes.": "测试产品界面并返回结构化 bug 报告，不修改代码。",
    "Test onboarding, docs, CLI/API affordances, and error recovery from a developer's perspective.": "从开发者视角测试上手流程、文档、CLI/API 易用性和错误恢复。",
    "Measure performance-sensitive surfaces and compare results against an agreed baseline.": "测量性能敏感界面，并与约定基线对比。",
    "Review trust boundaries, secrets, supply chain, and high-impact abuse paths.": "评审信任边界、密钥、供应链和高影响滥用路径。",
    "Inspect release queue state, open work, and version-slot risk without mutating the workspace.": "只读检查发布队列、未完成工作和版本槽风险。",
    "Document deployment configuration, production URLs, health checks, and release commands.": "记录部署配置、生产 URL、健康检查和发布命令。",
    "Prepare release checks, commits, pushes, PRs, and deploy handoff under strict approval.": "在严格审批下准备发布检查、commit、push、PR 和部署交接。",
    "Coordinate merge, deploy handoff, CI verification, and post-merge production checks.": "协调合并、部署交接、CI 验证和合并后的生产检查。",
    "Monitor a shipped surface for console errors, health failures, and performance regressions.": "监控已发布界面的控制台错误、健康失败和性能回归。",
    "Create missing documentation for a feature, module, or workflow from implementation evidence.": "基于实现证据为功能、模块或工作流补齐缺失文档。",
    "Update product and technical documentation so shipped behavior remains discoverable.": "更新产品和技术文档，确保已发布行为可被发现。",
    "Review recent engineering work, shipped outcomes, quality signals, and follow-up risks.": "复盘近期工程工作、已发布结果、质量信号和后续风险。",
    "Inspect and curate durable project learnings so future work can reuse prior decisions.": "检查并整理持久项目经验，方便后续工作复用既有决策。",
